function makeLocaleDict(overrides) {
  return { ...BASE_EN, ...overrides };
}


export const DICT = ALL_DICTIONARIES;

// Reverse lookup: lowercase English text -> dictionary key
export const EN_PHRASE_TO_KEY = {};
for (const [key, val] of Object.entries(BASE_EN)) {
  if (typeof val === "string") {
    EN_PHRASE_TO_KEY[val.toLowerCase()] = key;
    if (val.endsWith("…")) {
      EN_PHRASE_TO_KEY[val.slice(0, -1).toLowerCase()] = key;
    }
    if (val.endsWith("...")) {
      EN_PHRASE_TO_KEY[val.slice(0, -3).toLowerCase()] = key;
    }
  }
}

// Build comprehensive PHRASES map for ALL 41 supported languages
export const PHRASES = {};
for (const [locale, dict] of Object.entries(DICT)) {
  if (locale === "en") continue;
  const p = {};
  for (const [key, transVal] of Object.entries(dict)) {
    const enVal = BASE_EN[key];
    if (!enVal || !transVal || transVal === enVal) continue;
    p[enVal] = transVal;
    p[enVal.toLowerCase()] = transVal;
    p[enVal.toUpperCase()] = transVal;

    if (enVal.endsWith("…")) {
      const noDot = enVal.replace(/…$/, "").trim();
      p[noDot] = transVal;
      p[noDot.toLowerCase()] = transVal;
      p[noDot.toUpperCase()] = transVal;
    }
    if (enVal.endsWith("...")) {
      const noDot = enVal.replace(/\.{3}$/, "").trim();
      p[noDot] = transVal;
      p[noDot.toLowerCase()] = transVal;
      p[noDot.toUpperCase()] = transVal;
    }
  }
  PHRASES[locale] = p;
}
export function detectLocale() {
  // Once the user changes language in Settings, use that choice everywhere in
  // this page, even when the original URL supplied a startup locale.
  if (activeLocale && SUPPORTED.includes(activeLocale)) return activeLocale;
  try {
    if (typeof window !== "undefined") {
      const url = new URL(window.location.href);
      const q = url.searchParams.get("lang") || url.searchParams.get("locale");
      if (q && SUPPORTED.includes(q)) return q;
      const stored = localStorage.getItem(STORAGE_KEY);
      if (stored && SUPPORTED.includes(stored)) return stored;
    }
  } catch (_) {}
  try {
    if (typeof navigator !== "undefined") {
      const nav = (navigator.language || navigator.userLanguage || "").toLowerCase();
      if (nav.startsWith("zh-tw") || nav.startsWith("zh-hk")) return "zh-TW";
      if (nav.startsWith("zh")) return "zh-CN";
      const two = nav.slice(0, 2);
      if (SUPPORTED.includes(two)) return two;
    }
  } catch (_) {}
  return DEFAULT;
}

/** Sets and persists the user locale. */
export function setLocale(locale) {
  if (!SUPPORTED.includes(locale)) return false;
  activeLocale = locale;
  try {
    if (typeof localStorage !== "undefined") {
      localStorage.setItem(STORAGE_KEY, locale);
    }
  } catch (_) {}
  return true;
}

/** Gets the current locale. */
export function getLocale() {
  return detectLocale();
}

/** Lists all supported locale codes. */
export function supportedLocales() {
  return [...SUPPORTED];
}

/** Checks if a locale is supported. */
export function isSupported(locale) {
  return SUPPORTED.includes(locale);
}

/**
 * Returns translated string for key, falling back to English, then the key itself.
 */
export function t(key, locale = detectLocale()) {
  const dict = DICT[locale] || DICT[DEFAULT] || BASE_EN;
  if (dict && dict[key] !== undefined) return dict[key];
  const en = DICT[DEFAULT] || BASE_EN;
  if (en && en[key] !== undefined) return en[key];
  return key;
}

