    "sv": "Sök lokala växter, träd, örter...",
    "sw": "Tafuta mimea ya ndani, miti, mitishamba...",
    "tl": "Maghanap ng mga lokal na halaman, puno, damo...",
    "ms": "Cari tumbuhan, pokok, herba tempatan...",
    "fa": "جستجوی گیاهان محلی، درختان، گیاهان...",
