// ── Universal Translation Cache & Auto-Translation Engine ───────────
const TRANSLATION_CACHE = {};
let _cacheDirty = {};
let _cachePersistTimer = null;

export function getTranslationCache(locale = detectLocale()) {
  if (!locale) locale = detectLocale() || "en";
  if (!TRANSLATION_CACHE[locale]) {
    TRANSLATION_CACHE[locale] = {};
    if (typeof localStorage !== "undefined") {
      try {
        const saved = localStorage.getItem(`aurafisky_i18n_cache_${locale}`);
        if (saved) {
          const parsed = JSON.parse(saved);
          if (parsed && typeof parsed === "object") {
            Object.assign(TRANSLATION_CACHE[locale], parsed);
          }
        }
      } catch (_) {}
    }
  }
  return TRANSLATION_CACHE[locale];
}

function persistTranslationCache(locale) {
  _cacheDirty[locale] = true;
  if (_cachePersistTimer) return;
  _cachePersistTimer = setTimeout(() => {
    _cachePersistTimer = null;
    if (typeof localStorage === "undefined") return;
    for (const loc of Object.keys(_cacheDirty)) {
      try {
        localStorage.setItem(`aurafisky_i18n_cache_${loc}`, JSON.stringify(TRANSLATION_CACHE[loc] || {}));
      } catch (_) {}
    }
    _cacheDirty = {};
  }, 800);
}

export function hasTranslatableText(text) {
  if (!text || typeof text !== "string") return false;
  const trimmed = text.trim();
  if (trimmed.length < 2) return false;
  if (!/[a-zA-Z]/.test(trimmed)) return false;
  if (/^#[0-9a-f]{3,8}$/i.test(trimmed)) return false;
  if (/^(?:https?:\/\/|data:|blob:)/i.test(trimmed)) return false;
  return true;
}

let _pendingQueue = [];
let _batchTimeout = null;

function queueForTranslation(item) {
  _pendingQueue.push(item);
  if (_batchTimeout) return;
  _batchTimeout = setTimeout(() => {
    _batchTimeout = null;
    flushTranslationQueue();
  }, 25);
}

async function flushTranslationQueue() {
  const queue = _pendingQueue;
  _pendingQueue = [];
  if (queue.length === 0) return;

  const byLocale = new Map();
  for (const item of queue) {
    if (!byLocale.has(item.locale)) byLocale.set(item.locale, []);
    byLocale.get(item.locale).push(item);
  }

  for (const [locale, items] of byLocale.entries()) {
    if (locale === "en") continue;
    const cache = getTranslationCache(locale);
    const needed = new Map();

    for (const it of items) {
      const trimmed = it.text.trim();
      if (!hasTranslatableText(trimmed)) continue;
      if (cache[trimmed]) {
        applyItemTranslation(it, cache[trimmed]);
        continue;
      }
      if (!needed.has(trimmed)) needed.set(trimmed, []);
      needed.get(trimmed).push(it);
    }

    if (needed.size === 0) continue;

    const uniqueTexts = Array.from(needed.keys());
    const chunkSize = 25;
    for (let i = 0; i < uniqueTexts.length; i += chunkSize) {
      const chunk = uniqueTexts.slice(i, i + chunkSize);
      try {
        const hasInternalNewlines = chunk.some(t => t.includes('\n'));
        if (!hasInternalNewlines) {
          const url = `https://translate.googleapis.com/translate_a/single?client=gtx&sl=auto&tl=${encodeURIComponent(locale)}&dt=t&q=${encodeURIComponent(chunk.join('\n'))}`;
          const res = await fetch(url);
          if (res.ok) {
            const data = await res.json();
            const joined = data[0].map(x => x[0]).join('');
            const lines = joined.split('\n');
            if (lines.length === chunk.length) {
              for (let j = 0; j < chunk.length; j++) {
                const orig = chunk[j];
                const trans = lines[j].trim();
                if (trans) {
                  cache[orig] = trans;
                  const targets = needed.get(orig) || [];
                  for (const tgt of targets) applyItemTranslation(tgt, trans);
                }
              }
              continue;
            }
          }
        }

        // Individual fallback
        for (const orig of chunk) {
          try {
            const sUrl = `https://translate.googleapis.com/translate_a/single?client=gtx&sl=auto&tl=${encodeURIComponent(locale)}&dt=t&q=${encodeURIComponent(orig)}`;
            const sRes = await fetch(sUrl);
            if (sRes.ok) {
              const sData = await sRes.json();
              const sTrans = sData[0]?.[0]?.[0];
              if (sTrans) {
                const trans = sTrans.trim();
                cache[orig] = trans;
                const targets = needed.get(orig) || [];
                for (const tgt of targets) applyItemTranslation(tgt, trans);
              }
            }
          } catch (_) {}
        }
      } catch (err) {
        for (const orig of chunk) {
          try {
            const sUrl = `https://translate.googleapis.com/translate_a/single?client=gtx&sl=auto&tl=${encodeURIComponent(locale)}&dt=t&q=${encodeURIComponent(orig)}`;
            const sRes = await fetch(sUrl);
            if (sRes.ok) {
              const sData = await sRes.json();
              const sTrans = sData[0]?.[0]?.[0];
              if (sTrans) {
                const trans = sTrans.trim();
                cache[orig] = trans;
                const targets = needed.get(orig) || [];
                for (const tgt of targets) applyItemTranslation(tgt, trans);
              }
            }
          } catch (_) {}
        }
      }
    }
    persistTranslationCache(locale);
  }
}

function applyItemTranslation(item, translated) {
  const currentLocale = detectLocale();
  if (currentLocale !== item.locale) return;

  if (item.type === "text" && item.node.isConnected) {
    const orig = item.text;
    const matchLead = orig.match(/^\s*/);
    const matchTrail = orig.match(/\s*$/);
    const leading = matchLead ? matchLead[0] : "";
    const trailing = matchTrail ? matchTrail[0] : "";
    item.node.nodeValue = leading + translated + trailing;
  } else if (item.type === "attr" && item.element.isConnected) {
    item.element.setAttribute(item.attr, translated);
    if (item.attr === "value") item.element.value = translated;
  } else if (item.type === "option" && item.element.isConnected) {
    item.element.text = translated;
  } else if (item.type === "optgroup" && item.element.isConnected) {
    item.element.label = translated;
  }
}

export async function translateAsync(text, locale = detectLocale()) {
  if (!text || typeof text !== "string") return text;
  if (!locale || locale === "en") return text;
  const sync = translateText(text, locale);
  if (sync && sync !== text) return sync;
  const cache = getTranslationCache(locale);
  const trimmed = text.trim();
  if (cache[trimmed]) {
    return text.replace(trimmed, cache[trimmed]);
  }
  try {
    const url = `https://translate.googleapis.com/translate_a/single?client=gtx&sl=auto&tl=${encodeURIComponent(locale)}&dt=t&q=${encodeURIComponent(trimmed)}`;
    const res = await fetch(url);
    if (res.ok) {
      const data = await res.json();
      const trans = data[0]?.[0]?.[0]?.trim();
      if (trans) {
        cache[trimmed] = trans;
        persistTranslationCache(locale);
        return text.replace(trimmed, trans);
      }
    }
  } catch (_) {}
  return text;
}


