export function translateText(rawText, locale = detectLocale()) {
  if (!rawText || typeof rawText !== "string") return rawText;
  if (!locale || locale === "en") return rawText;

  const trimmed = rawText.trim();
  if (!trimmed) return rawText;

  // Trailing colon handler
  if (trimmed.endsWith(":")) {
    const withoutColon = trimmed.slice(0, -1).trim();
    const transColon = translateText(withoutColon, locale);
    if (transColon && transColon !== withoutColon) {
      return rawText.replace(trimmed, `${transColon}:`);
    }
  }

  // 1. Direct extended vocabulary check (instant dictionary for 40+ languages)
  if (EXTENDED_FEATURE_PHRASES[trimmed]?.[locale]) {
    return rawText.replace(trimmed, EXTENDED_FEATURE_PHRASES[trimmed][locale]);
  }
  const normLower = trimmed.toLowerCase();
  for (const [phrase, langMap] of Object.entries(EXTENDED_FEATURE_PHRASES)) {
    if (phrase.toLowerCase() === normLower && langMap[locale]) {
      return rawText.replace(trimmed, langMap[locale]);
    }
  }

  // 1b. Direct cache check
  const cache = getTranslationCache(locale);
  if (cache[trimmed]) {
    return rawText.replace(trimmed, cache[trimmed]);
  }

  // Emoji prefix handler (e.g. "🌅 Sunrise", "📡 Just now", "🔔 Alert me", "🌧️ Rain Chance")
  const emojiPrefixMatch = trimmed.match(/^((?:[\p{Extended_Pictographic}\u2000-\u3300\uFE00-\uFE0F\u200D\s])+)\s+([A-Za-z0-9\p{L}].*)$/u);
  if (emojiPrefixMatch) {
    const prefix = emojiPrefixMatch[1].trim();
    const rest = emojiPrefixMatch[2];
    const transRest = translateText(rest, locale);
    if (transRest && transRest !== rest) {
      if (transRest.startsWith(prefix)) {
        return rawText.replace(trimmed, transRest);
      }
      return rawText.replace(trimmed, `${prefix} ${transRest}`);
    }
  }

  // 2. Direct phrase lookup from PHRASES
  const pMap = PHRASES[locale] || {};
  if (pMap[trimmed]) {
    return rawText.replace(trimmed, pMap[trimmed]);
  }

  // Trailing ellipsis handler
  if (trimmed.endsWith("...") || trimmed.endsWith("…")) {
    const withoutDots = trimmed.replace(/\.{3}$|…$/, "").trim();
    if (pMap[withoutDots]) {
      const suffix = trimmed.endsWith("…") ? "…" : "...";
      return rawText.replace(trimmed, pMap[withoutDots] + suffix);
    }
  }

  // 3. Direct dictionary key check
  const fromT = t(trimmed, locale);
  if (fromT && fromT !== trimmed) {
    return rawText.replace(trimmed, fromT);
  }

  // 4. Reverse lookup: lowercase English text -> key -> localized string
  const norm = trimmed.toLowerCase();
  const revKey = EN_PHRASE_TO_KEY[norm];
  if (revKey) {
    const val = t(revKey, locale);
    if (val && val !== BASE_EN[revKey]) {
      return rawText.replace(trimmed, val);
    }
  }

  // Check without dots for reverse key
  if (norm.endsWith("...") || norm.endsWith("…")) {
    const normNoDots = norm.replace(/\.{3}$|…$/, "").trim();
    const revNoDots = EN_PHRASE_TO_KEY[normNoDots];
    if (revNoDots) {
      const val = t(revNoDots, locale);
      if (val && val !== BASE_EN[revNoDots]) {
        const suffix = trimmed.endsWith("…") ? "…" : "...";
        return rawText.replace(trimmed, val + suffix);
      }
    }
  }

  // 5. Dynamic patterns
  // Pattern: Sowing schedules (compound or single)
  // e.g. "· sow Sep-Oct-Nov · ~80 days" or "sow Jan-Feb-Mar-Oct-Nov · ~360 days"
  // or "Next window in ~7 months · sow Jun-Jul-Sep-Oct · ~110 days"
  // or "⏳ Next window in ~7 months"
  if (/\b(?:sow\s+[A-Za-z-]+|Next window in\s*~\d+\s*months?)\b/i.test(trimmed)) {
    let result = rawText;
    const nextMatch = trimmed.match(/^(?:⏳\s*)?Next window in ~(\d+)\s*months?/i);
    if (nextMatch) {
      const m = nextMatch[1];
      let transNext = `⏳ Next window in ~${m} months`;
      if (locale === "kn") transNext = `⏳ ಮುಂದಿನ ಬಿತ್ತನೆ ~${m} ತಿಂಗಳಲ್ಲಿ`;
      else if (locale === "hi") transNext = `⏳ ~${m} महीनों में अगली खिड़की`;
      else if (locale === "zh-CN") transNext = `⏳ 下个播种期约 ${m} 个月后`;
      else if (locale === "zh-TW") transNext = `⏳ 下個播種期約 ${m} 個月後`;
      else if (locale === "es") transNext = `⏳ Próxima ventana en ~${m} meses`;
      else if (SOW_LABELS_MAP[locale]?.next) {
        transNext = `⏳ ${SOW_LABELS_MAP[locale].next.replace(/~?%s/, `~${m}`)}`;
      }
      result = result.replace(nextMatch[0], transNext);
    }

    const sowMatch = trimmed.match(/\bsow\s+((?:(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)-?)+)(?:\s*·\s*~(\d+)\s*days)?/i);
    if (sowMatch) {
      const monthsStr = sowMatch[1];
      const days = sowMatch[2];
      const mTrans = monthsStr.split('-').map(m => getLocalizedMonthShort(m, locale)).join('-');
      const sowLbl = (locale === "kn" ? "ಬಿತ್ತನೆ" : (locale === "hi" ? "बुवाई" : (locale === "zh-CN" ? "播种期" : (locale === "zh-TW" ? "播種期" : (locale === "es" ? "siembra" : (SOW_LABELS_MAP[locale]?.sow || "sow"))))));
      const daysLbl = (locale === "kn" ? "ದಿನಗಳು" : (locale === "hi" ? "दिन" : (locale === "zh-CN" ? "天" : (locale === "zh-TW" ? "天" : (locale === "es" ? "días" : (SOW_LABELS_MAP[locale]?.days || "days"))))));

      let replacement = `${sowLbl} ${mTrans}`;
      if (days) {
        replacement += ` · ~${days} ${daysLbl}`;
      }
      result = result.replace(sowMatch[0], replacement);
    }

    if (result.includes("Sow now")) {
      const sowNowLbl = EXTENDED_FEATURE_PHRASES["Sow now"]?.[locale] || pMap["Sow now"] || "Sow now";
      result = result.replace("Sow now", sowNowLbl);
    }

    if (result !== rawText) return result;
  }

  // Pattern: N visible (celestial badges e.g. "4 visible")
  const visibleBadgeMatch = trimmed.match(/^(\d+)\s+visible$/i);
  if (visibleBadgeMatch) {
    const num = visibleBadgeMatch[1];
    if (locale === "kn") return rawText.replace(trimmed, `${num} ಗೋಚರಿಸುತ್ತವೆ`);
    if (locale === "hi") return rawText.replace(trimmed, `${num} दृश्य`);
    if (locale === "zh-CN") return rawText.replace(trimmed, `${num} 颗可见`);
    if (locale === "zh-TW") return rawText.replace(trimmed, `${num} 顆可見`);
    if (locale === "es") return rawText.replace(trimmed, `${num} visible${num === "1" ? "" : "s"}`);
    if (locale === "fr") return rawText.replace(trimmed, `${num} visible${num === "1" ? "" : "s"}`);
    if (locale === "de") return rawText.replace(trimmed, `${num} sichtbar`);
    const vWord = SOW_LABELS_MAP[locale]?.visible || "visible";
    return rawText.replace(trimmed, `${num} ${vWord}`);
  }

  // Pattern: Direction with altitude e.g. "SE (39°)"
  const dirAltMatch = trimmed.match(/^([A-Z]{1,3})\s*\(([+-]?\d+°)\)$/);
  if (dirAltMatch) {
    const dir = dirAltMatch[1];
    const alt = dirAltMatch[2];
    const dirTrans = EXTENDED_FEATURE_PHRASES[dir]?.[locale] || pMap[dir] || dir;
    if (dirTrans && dirTrans !== dir) {
      return rawText.replace(trimmed, `${dirTrans} (${alt})`);
    }
  }

  // Pattern: Alt: N° or Alt N°
  const altMatch = trimmed.match(/^(?:Alt|Altitude|ಎತ್ತರ|ऊंचाई|仰角|உயரம்|ఎత్తు|উচ্চতা|उंची|ઊંચાઈ|उन्नतिः):?\s*([+-]?\d+°?)$/i);
  if (altMatch) {
    const altWord = ALT_WORDS[locale] || EXTENDED_FEATURE_PHRASES["Altitude"]?.[locale] || "Alt";
    return rawText.replace(trimmed, `${altWord}: ${altMatch[1]}`);
  }

  // Pattern: Show All (N)
  const showAllMatch = trimmed.match(/^Show All\s*\((\d+)\)$/i);
  if (showAllMatch) {
    const showAllTrans = pMap["Show All"] || t("show_all", locale) || "Show All";
    return rawText.replace(trimmed, `${showAllTrans} (${showAllMatch[1]})`);
  }

  // Pattern: Show Fewer / Show Less
  if (/^Show Fewer$/i.test(trimmed)) {
    const trans = pMap["Show fewer"] || t("show_fewer", locale) || "Show fewer";
    return rawText.replace(trimmed, trans);
  }

  // Pattern: Stop N
  const stopMatch = trimmed.match(/^Stop\s*(\d+)$/i);
  if (stopMatch) {
    const stopTrans = pMap["Stop"] || t("stop", locale) || "Stop";
    return rawText.replace(trimmed, `${stopTrans} ${stopMatch[1]}`);
  }

  // Pattern: Stops (N)
  const stopsMatch = trimmed.match(/^Stops\s*\((\d+)\)$/i);
  if (stopsMatch) {
    const stopsTrans = pMap["Stops"] || t("stops", locale) || "Stops";
    return rawText.replace(trimmed, `${stopsTrans} (${stopsMatch[1]})`);
  }

  // Pattern: Next rain TIME
  const nextRainMatch = trimmed.match(/^(?:🌧️\s*)?Next rain\s+(.+)$/i);
  if (nextRainMatch) {
    const nextRainTrans = pMap["Next rain"] || t("next_rain", locale) || "Next rain";
    return rawText.replace(trimmed, `🌧️ ${nextRainTrans} ${nextRainMatch[1]}`);
  }

  // Pattern: Trust score (handles pure English, mixed, or localized)
  // e.g. "🎯 55% trust (temp 62%, wind 52%, precip 47%)" or "55% trust (温度 62%, 风速 52%, precipitation 47%)"
  const trustMatch = trimmed.match(/^(?:🎯\s*)?(\d+)%\s*(?:trust|置信度|ವಿಶ್ವಾಸಾರ್ಹತೆ|ವಿಶ್ವಾಸಾರ್ಹತೆ|विश्वसनीयता|વિશ્વસનીયતા|વિશ્વાસ|confianza|confiance|Vertrauen|fede|confiança|доверие|信頼度|신뢰도|ثقة|اعتماد|вирогідність|نம்பகத்தன்மை|విశ్వసనీయత|વિશ્વાસપાત્રતા)?\s*\((.+)\)$/i);
  if (trustMatch) {
    const pct = trustMatch[1];
    const inner = trustMatch[2];
    const nums = inner.match(/(\d+)%/g);
    if (nums && nums.length >= 3) {
      if (locale === "kn") {
        return rawText.replace(trimmed, `🎯 ${pct}% ವಿಶ್ವಾಸಾರ್ಹತೆ (ತಾಪ ${nums[0]}, ಗಾಳಿ ${nums[1]}, ಮಳೆ ${nums[2]})`);
      } else if (locale === "hi") {
        return rawText.replace(trimmed, `🎯 ${pct}% विश्वसनीयता (ताप ${nums[0]}, हवा ${nums[1]}, वर्षा ${nums[2]})`);
      } else if (locale === "ta") {
        return rawText.replace(trimmed, `🎯 ${pct}% நம்பகத்தன்மை (வெப்பம் ${nums[0]}, காற்று ${nums[1]}, மழை ${nums[2]})`);
      } else if (locale === "te") {
        return rawText.replace(trimmed, `🎯 ${pct}% విశ్వసనీయత (ఉష్ణోగ్రత ${nums[0]}, గాలి ${nums[1]}, వర్షం ${nums[2]})`);
      } else if (locale === "zh-CN") {
        return rawText.replace(trimmed, `🎯 ${pct}% 置信度 (温度 ${nums[0]}, 风速 ${nums[1]}, 降水 ${nums[2]})`);
      } else if (locale === "zh-TW") {
        return rawText.replace(trimmed, `🎯 ${pct}% 置信度 (溫度 ${nums[0]}, 風速 ${nums[1]}, 降水 ${nums[2]})`);
      } else if (locale === "es") {
        return rawText.replace(trimmed, `🎯 ${pct}% confianza (temp ${nums[0]}, viento ${nums[1]}, precip ${nums[2]})`);
      } else if (locale === "gu") {
        return rawText.replace(trimmed, `🎯 ${pct}% વિશ્વસનીયતા (તાપમાન ${nums[0]}, પવન ${nums[1]}, વરસાદ ${nums[2]})`);
      } else {
        const trustLbl = t("trust", locale) || "trust";
        const tempLbl = t("temperature", locale) || "temp";
        const windLbl = t("wind", locale) || "wind";
        const precipLbl = t("precipitation", locale) || "precip";
        return rawText.replace(trimmed, `🎯 ${pct}% ${trustLbl} (${tempLbl} ${nums[0]}, ${windLbl} ${nums[1]}, ${precipLbl} ${nums[2]})`);
      }
    }
  }

  // Pattern: Best time to be outside: ...
  const bestTimeMatch = trimmed.match(/^Best time to be outside:\s*(.+?)(?:\s+(?:overnight|\(overnight\)))?\.?$/i);
  if (bestTimeMatch) {
    const lbl = t("best_time_to_be_outside", locale) || "Best time to be outside";
    const span = bestTimeMatch[1].replace(/\.?$/, "");
    const isOvernight = /overnight/i.test(trimmed);
    const overLbl = isOvernight ? ` (${t("overnight", locale) || "overnight"})` : "";
    return rawText.replace(trimmed, `${lbl}: ${span}${overLbl}.`);
  }

  // Pattern: Weather condition with temp and feels
  // e.g. "Light drizzle · 29° (feels 33°)" or "Partly cloudy · 38° (feels 39°)"
  const weatherFeelsMatch = trimmed.match(/^([^·•\n]+?)\s*[·•]\s*(-?\d+°)\s*(?:\((?:feels|ಅನಿಸಿಕೆ|ಅನಿಸಿಕೆ ತಾಪಮಾನ|અનુભવાય છે|체감|체감 온도|体感|体感温度|sensação|ressenti|gefühlt|percebida|чувствуется|महसूस|महसूस तापमान)\s*(-?\d+°)\))?$/i);
  if (weatherFeelsMatch) {
    const rawDesc = weatherFeelsMatch[1].trim();
    const temp = weatherFeelsMatch[2];
    const feelsTemp = weatherFeelsMatch[3];
    const transDesc = translateText(rawDesc, locale) || rawDesc;
    if (feelsTemp) {
      const feelsLbl = t("feels_like", locale) || "feels";
      return rawText.replace(trimmed, `${transDesc} · ${temp} (${feelsLbl} ${feelsTemp})`);
    } else {
      return rawText.replace(trimmed, `${transDesc} · ${temp}`);
    }
  }

  // Pattern: Time window with overnight and duration
  // e.g. "11:00 PM – 12:00 PM (overnight) (14h)" or "7:00 PM – 9:00 AM (overnight) (15h)"
  const timeWindowMatch = trimmed.match(/^(\d{1,2}:\d{2}\s*(?:AM|PM)\s*[–\-]\s*\d{1,2}:\d{2}\s*(?:AM|PM))(?:\s+\(overnight\))?(?:\s+\((\d+h)\))?$/i);
  if (timeWindowMatch) {
    const span = timeWindowMatch[1];
    const isOvernight = /\(overnight\)/i.test(trimmed);
    const dur = timeWindowMatch[2] ? ` (${timeWindowMatch[2]})` : "";
    const overLbl = isOvernight ? ` (${t("overnight", locale) || "overnight"})` : "";
    return rawText.replace(trimmed, `${span}${overLbl}${dur}`);
  }

  // Pattern: Rain expected around ...
  const rainExpMatch = trimmed.match(/^Rain expected around\s+(.+?)(?:\s*[—–\-]\s*(.+))?$/i);
  if (rainExpMatch) {
    const timeStr = rainExpMatch[1].trim();
    const suffix = rainExpMatch[2]?.trim();
    const lbl = t("rain_expected_around", locale) || "Rain expected around";
    const umbrellaLbl = t("keep_umbrella_handy", locale) || "keep the umbrella handy.";
    let res = `${lbl} ${timeStr}`;
    if (suffix) res += ` — ${umbrellaLbl}`;
    return rawText.replace(trimmed, res);
  }

  // Pattern: Rain N% peak over 24h — low concern
  const rainPeakMatch = trimmed.match(/^(?:(?:🌧️\s*)?(?:(?:Rain|मಳೆ|बारिश|વરસાદ|மழை|వర్షం|മഴ|বৃষ্টি)\s+)?|)(\d+)%\s*peak over 24h(?:\s*[—–\-]\s*(.+))?$/i);
  if (rainPeakMatch) {
    const pct = rainPeakMatch[1];
    const hasRainWord = /Rain|मಳೆ|बारिश|વરસાદ|மழை|వర్షం|മഴ|বৃষ্টি/i.test(trimmed);
    const rLbl = RAIN_WORDS[locale] || t("precipitation", locale) || "Rain";
    const pLbl = t("peak_over_24h", locale) || "peak over 24h — low concern";
    return rawText.replace(trimmed, hasRainWord ? `${rLbl} ${pct}% ${pLbl}` : `${pct}% ${pLbl}`);
  }

  // Pattern: N% chance within 6 hours — plan around it
  const rain6hMatch = trimmed.match(/^(?:(?:🌧️\s*)?(?:(?:Rain|मಳೆ|बारिश|વરસાદ|மழை|వర్షం|മഴ|বৃষ্টি)\s+)?|)(\d+)%\s*chance within 6 hours(?:\s*[—–\-]\s*(.+))?$/i);
  if (rain6hMatch) {
    const pct = rain6hMatch[1];
    const hasRainWord = /Rain|मಳೆ|बारिश|વરસાદ|மழை|వర్షం|മഴ|বৃষ্টি/i.test(trimmed);
    const rLbl = RAIN_WORDS[locale] || t("precipitation", locale) || "Rain";
    const cLbl = t("chance_within_6_hours", locale) || "chance within 6 hours — plan around it";
    return rawText.replace(trimmed, hasRainWord ? `${rLbl} ${pct}% ${cLbl}` : `${pct}% ${cLbl}`);
  }

  // Pattern: Today's range 23° - 31°
  const rangeMatch = trimmed.match(/^Today's range\s*(.+)$/i);
  if (rangeMatch) {
    const rLbl = t("todays_range", locale) || "Today's range";
    return rawText.replace(trimmed, `${rLbl} ${rangeMatch[1]}`);
  }

  // Pattern: Best outdoor window ...
  const bestOutdoorMatch = trimmed.match(/^Best outdoor window\s*(.+)$/i);
  if (bestOutdoorMatch) {
    const lbl = t("best_outdoor_window_label", locale) || t("best_outdoor_window", locale) || "Best outdoor window";
    let rest = bestOutdoorMatch[1];
    if (rest.includes("(overnight)")) {
      rest = rest.replace("(overnight)", `(${t("overnight", locale) || "overnight"})`);
    }
    return rawText.replace(trimmed, `${lbl} ${rest}`);
  }

  // Pattern: Daylight ...
  const daylightMatch = trimmed.match(/^Daylight\s+(.+)$/i);
  if (daylightMatch) {
    const lbl = t("daylight", locale) || "Daylight";
    return rawText.replace(trimmed, `${lbl} ${daylightMatch[1]}`);
  }

  // Pattern: Right now ...
  const rightNowMatch = trimmed.match(/^Right now\s*(.*)$/i);
  if (rightNowMatch) {
    const rnLbl = t("right_now", locale) || "Right now";
    let rest = rightNowMatch[1]?.trim();
    if (rest) {
      for (const [wmoKey, wmoEn] of [
        ["clear_sky", "Clear sky"], ["mainly_clear", "Mainly clear"],
        ["partly_cloudy", "Partly cloudy"], ["overcast", "Overcast"],
        ["foggy", "Foggy"], ["light_drizzle", "Light drizzle"],
        ["moderate_drizzle", "Moderate drizzle"], ["dense_drizzle", "Dense drizzle"],
        ["slight_rain", "Slight rain"], ["moderate_rain", "Moderate rain"],
        ["heavy_rain", "Heavy rain"], ["thunderstorm", "Thunderstorm"]
      ]) {
        if (rest.includes(wmoEn)) {
          const trans = t(wmoKey, locale);
          if (trans && trans !== wmoEn) rest = rest.replace(wmoEn, trans);
        }
      }
      const fMatch = rest.match(/feels\s+(\d+)°/i);
      if (fMatch) {
        const fLbl = t("feels", locale) || "feels";
        rest = rest.replace(fMatch[0], `${fLbl} ${fMatch[1]}°`);
      }
      return rawText.replace(trimmed, `${rnLbl} ${rest}`);
    }
    return rawText.replace(trimmed, rnLbl);
  }

  // Pattern: Generated from your live forecast ...
  if (/^Generated from your live forecast/i.test(trimmed)) {
    return rawText.replace(trimmed, t("generated_live_forecast", locale) || trimmed);
  }

  // Pattern: Map Key, Elevation Key, Temperature Scale
  if (/^Map Key$/i.test(trimmed)) return rawText.replace(trimmed, t("map_key", locale) || "Map Key");
  if (/^Elevation Key$/i.test(trimmed)) return rawText.replace(trimmed, t("elevation_key", locale) || "Elevation Key");
  if (/^Temperature Scale$/i.test(trimmed)) return rawText.replace(trimmed, t("temperature_scale", locale) || "Temperature Scale");

  // Pattern: feels N°
  const feelsMatch = trimmed.match(/\bfeels\s+(\d+)°/i);
  if (feelsMatch) {
    const fLbl = t("feels", locale) || "feels";
    rawText = rawText.replace(feelsMatch[0], `${fLbl} ${feelsMatch[1]}°`);
  }

  // Pattern: (overnight)
  if (trimmed.includes("(overnight)")) {
    const oLbl = t("overnight", locale) || "overnight";
    rawText = rawText.replace("(overnight)", `(${oLbl})`);
  }

  // Pattern: arriving in ~Nh from the DIR
  const arriveMatch = trimmed.match(/arriving in ~(\d+)h from the ([A-Z]+)/i);
  if (arriveMatch) {
    const hours = arriveMatch[1];
    const dir = arriveMatch[2];
    if (locale === "kn") return rawText.replace(arriveMatch[0], `~${hours} ಗಂಟೆಯಲ್ಲಿ ${dir} ನಿಂದ ಬರುತ್ತಿದೆ`);
    if (locale === "hi") return rawText.replace(arriveMatch[0], `~${hours} घंटे में ${dir} से आ रहा है`);
    if (locale === "zh-CN") return rawText.replace(arriveMatch[0], `约 ${hours} 小时后自 ${dir} 抵达`);
    if (locale === "zh-TW") return rawText.replace(arriveMatch[0], `約 ${hours} 小時後自 ${dir} 抵達`);
    if (locale === "ja") return rawText.replace(arriveMatch[0], `約 ${hours} 時間後に ${dir} から到達`);
    if (locale === "es") return rawText.replace(arriveMatch[0], `llegando en ~${hours}h desde el ${dir}`);
    if (locale === "fr") return rawText.replace(arriveMatch[0], `arrivant dans ~${hours}h depuis ${dir}`);
    if (locale === "de") return rawText.replace(arriveMatch[0], `trifft in ~${hours}h aus ${dir} ein`);
  }

  // Pattern: LIVE WEATHER INTELLIGENCE • CITY
  const lwiMatch = trimmed.match(/^LIVE WEATHER INTELLIGENCE\s*•\s*(.+)$/i);
  if (lwiMatch) {
    const lwiTrans = pMap["Live Weather Intelligence"] || t("live_weather_intelligence", locale) || "Live Weather Intelligence";
    return rawText.replace(trimmed, `${lwiTrans.toUpperCase()} • ${lwiMatch[1]}`);
  }

  // Pattern: ... limiting comfort
  if (trimmed.includes("limiting comfort")) {
    const comfortTrans = pMap["limiting comfort"] || t("limiting_comfort", locale) || "limiting comfort";
    let res = rawText.replace("limiting comfort", comfortTrans);
    ["Temperature", "Humidity", "Wind", "Air Quality", "Precipitation", "Cloud Cover", "UV"].forEach(param => {
      const pTrans = pMap[param] || t(param.toLowerCase().replace(/\s+/g, "_"), locale);
      if (pTrans) res = res.replace(new RegExp(`\\b${param}\\b`, "g"), pTrans);
    });
    return res;
  }

  // Pattern: Category (N) e.g. Trees (26), Wildflowers (8), Herbs (7), Stops (2), All (92)
  const countMatch = trimmed.match(/^([A-Za-z\s/&·-]+)\s*\((\d+)\)$/i);
  if (countMatch) {
    const cat = countMatch[1].trim();
    const num = countMatch[2];
    const transCat = translateText(cat, locale);
    if (transCat && transCat !== cat) {
      return rawText.replace(trimmed, `${transCat} (${num})`);
    }
  }

  // Pattern: Forecast updated ...
  const fUpdMatch = trimmed.match(/^Forecast updated\s+(.+)$/i);
  if (fUpdMatch) {
    const fLbl = t("forecast_updated", locale) || "Forecast updated";
    const sub = translateText(fUpdMatch[1], locale);
    return rawText.replace(trimmed, `${fLbl} ${sub}`);
  }

  // Pattern: N min ago / Updated N min ago
  const minAgoMatch = trimmed.match(/^(?:Updated\s+)?(\d+)\s*(?:m|min|mins|minutes?)\s*ago$/i);
  if (minAgoMatch) {
    const mins = minAgoMatch[1];
    const isUpdated = /^Updated/i.test(trimmed);
    if (locale === "kn") return rawText.replace(trimmed, isUpdated ? `${mins} ನಿಮಿಷಗಳ ಹಿಂದೆ ನವೀಕರಿಸಲಾಗಿದೆ` : `${mins} ನಿಮಿಷಗಳ ಹಿಂದೆ`);
    if (locale === "hi") return rawText.replace(trimmed, isUpdated ? `${mins} मिनट पहले अपडेट किया गया` : `${mins} मिनट पहले`);
    if (locale === "zh-CN") return rawText.replace(trimmed, isUpdated ? `${mins} 分钟前更新` : `${mins} 分钟前`);
    if (locale === "zh-TW") return rawText.replace(trimmed, isUpdated ? `${mins} 分鐘前更新` : `${mins} 分鐘前`);
    if (locale === "es") return rawText.replace(trimmed, isUpdated ? `actualizado hace ${mins} min` : `hace ${mins} min`);
    if (locale === "fr") return rawText.replace(trimmed, isUpdated ? `mis à jour il y a ${mins} min` : `il y a ${mins} min`);
    if (locale === "de") return rawText.replace(trimmed, isUpdated ? `vor ${mins} Min. aktualisiert` : `vor ${mins} Min.`);
  }

  // Pattern: N observed nearby
  const obsNearbyMatch = trimmed.match(/^(\d+)\s+observed nearby$/i);
  if (obsNearbyMatch) {
    const count = obsNearbyMatch[1];
    if (OBS_NEARBY_WORDS[locale]) {
      if (locale === "zh-CN" || locale === "zh-TW") {
        return rawText.replace(trimmed, `${OBS_NEARBY_WORDS[locale]} ${count} 种`);
      }
      return rawText.replace(trimmed, `${count} ${OBS_NEARBY_WORDS[locale]}`);
    }
    return rawText.replace(trimmed, `${count} observed nearby`);
  }

  // Pattern: N% rain risk in the next 6 hours
  const rainRiskMatch = trimmed.match(/^(\d+)%\s*rain risk in the next 6 hours$/i);
  if (rainRiskMatch) {
    const pct = rainRiskMatch[1];
    if (locale === "kn") return rawText.replace(trimmed, `ಮುಂದಿನ 6 ಗಂಟೆಗಳಲ್ಲಿ ${pct}% ಮಳೆಯ ಸಾಧ್ಯತೆ`);
    if (locale === "hi") return rawText.replace(trimmed, `अगले 6 घंटों में ${pct}% बारिश का जोखिम`);
    if (locale === "zh-CN") return rawText.replace(trimmed, `未来 6 小时内降雨概率 ${pct}%`);
    if (locale === "zh-TW") return rawText.replace(trimmed, `未來 6 小時內降雨機率 ${pct}%`);
    if (locale === "es") return rawText.replace(trimmed, `${pct}% de riesgo de lluvia en las próximas 6 horas`);
  }

  // Pattern: Gusts up to N km/h — ...
  const gustsMatch = trimmed.match(/^Gusts up to (\d+)\s*km\/h\s*[—–\-]\s*(.+)$/i);
  if (gustsMatch) {
    const spd = gustsMatch[1];
    if (locale === "kn") return rawText.replace(trimmed, `ಗಂಟೆಗೆ ${spd} ಕಿಮೀ ವೇಗದ ಬಿರುಗಾಳಿ — ಕುರ್ಚಿಗಳು, ಛತ್ರಿಗಳು`);
    if (locale === "hi") return rawText.replace(trimmed, `${spd} किमी/घंटा तक के झोंके — कुर्सियां, छाते सुरक्षित करें`);
    if (locale === "zh-CN") return rawText.replace(trimmed, `阵风高达 ${spd} 公里/小时 — 妥善固定室外物品`);
    if (locale === "es") return rawText.replace(trimmed, `Rachas de hasta ${spd} km/h — asegurar objetos sueltos`);
  }

  // Pattern: Air quality is N AQI — ...
  const aqiTodoMatch = trimmed.match(/^Air quality is (\d+)\s*AQI\s*[—–\-]\s*(.+)$/i);
  if (aqiTodoMatch) {
    const aqi = aqiTodoMatch[1];
    if (locale === "kn") return rawText.replace(trimmed, `ಗಾಳಿಯ ಗುಣಮಟ್ಟ ${aqi} AQI — ತೀವ್ರ ವ್ಯಾಯಾಮಗಳನ್ನು ಒಳಾಂಗಣದಲ್ಲಿ ಮಾಡಿ`);
    if (locale === "hi") return rawText.replace(trimmed, `वायु गुणवत्ता ${aqi} AQI है — व्यायाम घर के अंदर करें`);
    if (locale === "zh-CN") return rawText.replace(trimmed, `空气质量指数 ${aqi} AQI — 请在室内锻炼`);
    if (locale === "es") return rawText.replace(trimmed, `Calidad del aire ${aqi} AQI — ejercitarse en interiores`);
  }

  // Pattern: UV N — ...
  const uvTodoMatch = trimmed.match(/^UV\s*(\d+)\s*[—–\-]\s*(.+)$/i);
  if (uvTodoMatch) {
    const uvVal = uvTodoMatch[1];
    if (locale === "kn") return rawText.replace(trimmed, `ಯುವಿ ${uvVal} — ಮಧ್ಯಾಹ್ನದ ವೇಳೆ SPF 30+ ಮತ್ತು ಟೋಪಿ ಧರಿಸಿ`);
    if (locale === "hi") return rawText.replace(trimmed, `यूवी ${uvVal} — धूप से बचाव के लिए सनस्क्रीन और टोपी पहनें`);
    if (locale === "zh-CN") return rawText.replace(trimmed, `紫外线 ${uvVal} — 中午注意涂防晒霜并佩戴遮阳帽`);
    if (locale === "es") return rawText.replace(trimmed, `UV ${uvVal} — protector solar SPF 30+ y sombrero cerca del mediodía`);
  }

  // Pattern: Leg N: ...
  const legMatch = trimmed.match(/^Leg\s*(\d+):\s*(.+)$/i);
  if (legMatch) {
    const legNum = legMatch[1];
    const restLeg = legMatch[2];
    if (locale === "kn") return rawText.replace(trimmed, `ಹಂತ ${legNum}: ${restLeg}`);
    if (locale === "hi") return rawText.replace(trimmed, `चरण ${legNum}: ${restLeg}`);
    if (locale === "zh-CN") return rawText.replace(trimmed, `航段 ${legNum}: ${restLeg}`);
    if (locale === "es") return rawText.replace(trimmed, `Etapa ${legNum}: ${restLeg}`);
  }

  // Pattern: START (A) / DESTINATION (B)
  if (/^START\s*\(A\)$/i.test(trimmed)) {
    if (locale === "kn") return rawText.replace(trimmed, "ಪ್ರಾರಂಭದ ಸ್ಥಳ (A)");
    if (locale === "hi") return rawText.replace(trimmed, "आरंभ (A)");
    if (locale === "zh-CN") return rawText.replace(trimmed, "起点 (A)");
    if (locale === "es") return rawText.replace(trimmed, "Inicio (A)");
  }
  if (/^DESTINATION\s*\(B\)$/i.test(trimmed)) {
    if (locale === "kn") return rawText.replace(trimmed, "ತಲುಪುವ ಸ್ಥಳ (B)");
    if (locale === "hi") return rawText.replace(trimmed, "गंतव्य (B)");
    if (locale === "zh-CN") return rawText.replace(trimmed, "终点 (B)");
    if (locale === "es") return rawText.replace(trimmed, "Destino (B)");
  }

  // Pattern: ETA ...
  const etaMatch = trimmed.match(/^ETA\s+(.+)$/i);
  if (etaMatch) {
    if (locale === "kn") return rawText.replace(trimmed, `ತಲುಪುವ ಸಮಯ ${etaMatch[1]}`);
    if (locale === "hi") return rawText.replace(trimmed, `आगमन ${etaMatch[1]}`);
    if (locale === "zh-CN") return rawText.replace(trimmed, `预计到达 ${etaMatch[1]}`);
    if (locale === "es") return rawText.replace(trimmed, `Llegada ${etaMatch[1]}`);
  }

  return rawText;
}
export function translateDOM(root = (typeof document !== "undefined" ? document.body : null), locale = detectLocale()) {
  if (!root || typeof document === "undefined") return;
  if (!locale) locale = detectLocale();

  const rootElement = root.nodeType === Node.ELEMENT_NODE ? root : null;
  const elementsMatching = (selector) => {
    const matches = [];
    if (rootElement?.matches(selector)) matches.push(rootElement);
    if (root.querySelectorAll) matches.push(...root.querySelectorAll(selector));
    return matches;
  };

  // 1. Direct explicit translations for known key UI targets
  const targetMap = {
    copyAddressBtnText: "copy",
    toggleAddressCardText: "details",
    discoveriesHeaderTitle: "live_weather_intelligence_safety",
    settingsUnitsLabel: "units_metric",
    settingsUnitsSub: "units_metric_sub",
    settingsAppLanguageLabel: "settings_app_language",
    settingsAppLanguageSub: "settings_app_language_sub",
    elevationLegendTitle: "elevation_key"
  };
  for (const [id, key] of Object.entries(targetMap)) {
    const el = rootElement?.id === id
      ? rootElement
      : (root.querySelector ? root.querySelector("#" + id) : null);
    if (el) {
      const translated = t(key, locale) || el.textContent;
      if (el.textContent !== translated) el.textContent = translated;
    }
  }
  const briefingBtn = rootElement?.id === "briefingBtn"
    ? rootElement
    : (root.querySelector ? root.querySelector("#briefingBtn") : null);
  if (briefingBtn) {
    const translated = `📡 ${t("generate_briefing", locale) || "Generate Briefing"}`;
    if (briefingBtn.textContent !== translated) briefingBtn.textContent = translated;
  }

  // 2. Translate <select> options (except settingsAppLanguageSelect)
  try {
    elementsMatching("option").forEach(opt => {
      if (opt.closest("#settingsAppLanguageSelect")) return;
      if (!opt.hasAttribute("data-orig-text")) opt.setAttribute("data-orig-text", opt.text);
      const original = opt.getAttribute("data-orig-text");
      const translated = translateText(original, locale);
      if (translated && translated !== original && opt.text !== translated) {
        opt.text = translated;
      } else if (locale === "en" && opt.text !== original) {
        opt.text = original;
      } else if (locale !== "en" && hasTranslatableText(original)) {
        queueForTranslation({
          type: "option",
          element: opt,
          text: original,
          locale
        });
      }
    });

    elementsMatching("optgroup[label]").forEach(group => {
      if (!group.hasAttribute("data-orig-label")) {
        group.setAttribute("data-orig-label", group.label);
      }
      const original = group.getAttribute("data-orig-label");
      const translated = translateText(original, locale);
      if (translated && translated !== original && group.label !== translated) {
        group.label = translated;
      } else if (locale === "en" && group.label !== original) {
        group.label = original;
      } else if (locale !== "en" && hasTranslatableText(original)) {
        queueForTranslation({
          type: "optgroup",
          element: group,
          text: original,
          locale
        });
      }
    });
  } catch (_) {}

  // 3. TreeWalker for all text nodes
  try {
    if (root.nodeType === Node.TEXT_NODE && root.nodeValue?.trim()) {
      if (root._origText == null) root._origText = root.nodeValue;
      const translated = translateText(root._origText, locale);
      if (translated && translated !== root._origText) {
        root.nodeValue = translated;
      } else if (locale === "en") {
        root.nodeValue = root._origText;
      } else if (hasTranslatableText(root._origText)) {
        queueForTranslation({
          type: "text",
          node: root,
          text: root._origText,
          locale
        });
      }
    }

    const walker = document.createTreeWalker(
      root,
      NodeFilter.SHOW_TEXT,
      {
        acceptNode(node) {
          if (!node.nodeValue || !node.nodeValue.trim()) return NodeFilter.FILTER_REJECT;
          const parent = node.parentElement;
          if (!parent) return NodeFilter.FILTER_REJECT;
          const tag = parent.tagName.toLowerCase();
          if (tag === "script" || tag === "style" || tag === "textarea" || tag === "code" || tag === "pre" || tag === "option") {
            return NodeFilter.FILTER_REJECT;
          }
          if (parent.closest && (parent.closest("#settingsAppLanguageSelect") || parent.classList?.contains("notranslate"))) {
            return NodeFilter.FILTER_REJECT;
          }
          return NodeFilter.FILTER_ACCEPT;
        }
      }
    );

    const textNodes = [];
    while (walker.nextNode()) {
      textNodes.push(walker.currentNode);
    }

    for (const node of textNodes) {
      if (node._origText == null) {
        node._origText = node.nodeValue;
      }
      const orig = node._origText;
      const translated = translateText(orig, locale);
      if (translated && translated !== orig) {
        node.nodeValue = translated;
      } else if (locale === "en" && orig) {
        node.nodeValue = orig;
      } else if (locale !== "en" && hasTranslatableText(orig)) {
        queueForTranslation({
          type: "text",
          node,
          text: orig,
          locale
        });
      }
    }
  } catch (err) {
    /* ignore tree walker error */
  }

  // 4. Attributes used by form fields and accessible controls
  try {
    const attrElements = elementsMatching("[placeholder], [title], [aria-label], [aria-description], [aria-placeholder], [alt], input[type='button'][value], input[type='submit'][value]");
    attrElements.forEach(el => {
      if (el.id === "settingsAppLanguageSelect") return;
      ["placeholder", "title", "aria-label", "aria-description", "aria-placeholder", "alt", "value"].forEach(attr => {
        if (attr === "value" && !/^(button|submit)$/i.test(el.type || "")) return;
        const val = el.getAttribute(attr);
        if (val && val.trim()) {
          const origKey = `data-orig-${attr}`;
          const origVal = el.getAttribute(origKey) || val;
          if (!el.hasAttribute(origKey)) el.setAttribute(origKey, origVal);
          const transVal = translateText(origVal, locale);
          if (transVal && transVal !== origVal && val !== transVal) {
            el.setAttribute(attr, transVal);
            if (attr === "value") el.value = transVal;
          } else if (locale === "en" && val !== origVal) {
            el.setAttribute(attr, origVal);
            if (attr === "value") el.value = origVal;
          } else if (locale !== "en" && hasTranslatableText(origVal)) {
            queueForTranslation({
              type: "attr",
              element: el,
              attr,
              text: origVal,
              locale
            });
          }
        }
      });
    });
  } catch (_) {}
}

let externalTranslationRefreshTimer = null;

/** Reapply the page translator after a feature replaces its live DOM. */
export function refreshExternalTranslation(locale = detectLocale()) {
  if (!locale || locale === "en" || typeof document === "undefined") return false;
  if (externalTranslationRefreshTimer !== null) {
    clearTimeout(externalTranslationRefreshTimer);
  }
  externalTranslationRefreshTimer = setTimeout(() => {
    externalTranslationRefreshTimer = null;
    const combo = document.querySelector(".goog-te-combo");
    if (!combo) return;
    if (combo.value !== locale) combo.value = locale;
    combo.dispatchEvent(new Event("change"));
  }, 120);
  return true;
}

